#include <zephyr/kernel.h>
#include <stdint.h>
#include <aes.h>
#include <string.h>

#include <zephyr/logging/log.h>
LOG_MODULE_REGISTER(main, LOG_LEVEL_DBG);

const uint8_t flag[AES_BLOCKLEN] = "NNS{faake_flaag}";
const uint8_t iv[AES_BLOCKLEN] = { 0x10, 0x9a, 0x41, 0xbc, 0xa7, 0x71, 0xbd, 0x4b, 0xe3, 0x52, 0x27, 0x71, 0x2f, 0xd8, 0x63, 0x98 };
char havamal[] = "Gáttir allar, áðr gangi fram, um skoðask skyli, um skyggnast skyli, því at óvíst er at vita, hvar óvinir sitja á fleti fyrir. Gefendr heilir! Gestr er inn kominn, hvar skal sitja sjá? Mjök er bráðr, sá er á bröndum skal síns of freista frama. Elds er þörf, þeims inn er kominn ok á kné kalinn; matar ok váða er manni þörf, þeim er hefr um fjall farit. Vatns er þörf, þeim er til verðar kemr, þerru ok þjóðlaðar, góðs of æðis, ef sér geta mætti, orðs ok endrþögu. Vits er þörf, þeim er víða ratar; dælt er heima hvat; at augabragði verðr, sá er ekki kann ok með snotrum sitr. At hyggjandi sinni skyli-t maðr hræsinn vera, heldr gætinn at geði; þá er horskr ok þögull kemr heimisgarða til, sjaldan verðr víti vörum, því at óbrigðra vin fær maðr aldregi en mannvit mikit. Inn vari gestr, er til verðar kemr, þunnu hljóði þegir, eyrum hlýðir, en augum skoðar; svá nýsisk fróðra hverr fyrir. Hinn er sæll, er sér of getr lof ok líknstafi; ódælla er við þat, er maðr eiga skal annars brjóstum í. Sá er sæll, er sjalfr of á lof ok vit, meðan lifir; því at ill ráð hefr maðr oft þegit annars brjóstum ór. Byrði betri berr-at maðr brautu at en sé mannvit mikit; auði betra þykkir þat í ókunnum stað; slíkt er válaðs vera. Byrði betri berr-at maðr brautu at en sé mannvit mikit; vegnest verra vegr-a hann velli at en sé ofdrykkja öls. Er-a svá gótt sem gótt kveða öl alda sona, því at færa veit, er fleira drekkr síns til geðs gumi. Óminnishegri heitir sá er yfir ölðrum þrumir, hann stelr geði guma; þess fugls fjöðrum ek fjötraðr vark í garði Gunnlaðar. Ölr ek varð, varð ofrölvi at ins fróða Fjalars; því er ölðr bazt, at aftr of heimtir hverr sitt geð gumi. Þagalt ok hugalt skyli þjóðans barn ok vígdjarft vera; glaðr ok reifr skyli gumna hverr, unz sinn bíðr bana. Ósnjallr maðr hyggsk munu ey lifa, ef hann við víg varask; en elli gefr hánum engi frið, þótt hánum geirar gefi. Kópir afglapi er til kynnis kemr, þylsk hann um eða þrumir; allt er senn, ef hann sylg of getr, uppi er þá geð guma. Sá einn veit er víða ratar ok hefr fjölð of farit, hverju geði stýrir gumna hverr, sá er vitandi er vits. Haldi-t maðr á keri, drekki þó at hófi mjöð, mæli þarft eða þegi, ókynnis þess vár þik engi maðr, at þú gangir snemma at sofa. Gráðugr halr, nema geðs viti, etr sér aldrtrega; oft fær hlægis, er með horskum kemr, manni heimskum magi. Hjarðir þat vitu, nær þær heim skulu, ok ganga þá af grasi; en ósviðr maðr kann ævagi síns of mál maga. Vesall maðr ok illa skapi hlær at hvívetna; hittki hann veit, er hann vita þyrfti, at hann er-a vamma vanr. Ósviðr maðr vakir um allar nætr ok hyggr at hvívetna; þá er móðr, er at morgni kemr, allt er víl sem var. Ósnotr maðr hyggr sér alla vera viðhlæjendr vini; hittki hann fiðr, þótt þeir um hann fár lesi, ef hann með snotrum sitr. Ósnotr maðr hyggr sér alla vera viðhlæjendr vini; þá þat finnr, er at þingi kemr, at hann á formælendr fáa. Ósnotr maðr þykkisk allt vita, ef hann á sér í vá veru; hittki hann veit, hvat hann skal við kveða, ef hans freista firar. Ósnotr maðr, er með aldir kemr, þat er bazt, at hann þegi; engi þat veit, at hann ekki kann, nema hann mæli til margt; veit-a maðr, hinn er vettki veit, þótt hann mæli til margt. Fróðr sá þykkisk, er fregna kann ok segja it sama; eyvitu leyna megu ýta synir, því er gengr um guma. Ærna mælir, sá er æva þegir, staðlausu stafi; hraðmælt tunga, nema haldendr eigi, oft sér ógótt of gelr. At augabragði skal-a maðr annan hafa, þótt til kynnis komi; margr þá fróðr þykkisk, ef hann freginn er-at ok nái hann þurrfjallr þruma. Fróðr þykkisk, sá er flótta tekr, gestr at gest hæðinn; veit-a görla, sá er of verði glissir, þótt hann með grömum glami. Gumnar margir erusk gagnhollir, en at virði vrekask; aldar róg þat mun æ vera, órir gestr við gest. Árliga verðar skyli maðr oft fáa, nema til kynnis komi: str ok snópir, lætr sem solginn sé ok kann fregna at fáu. Afhvarf mikit er til ills vinar, þótt á brautu búi, en til góðs vinar liggja gagnvegir, þótt hann sé firr farinn. Ganga skal, skal-a gestr vera ey í einum stað; ljúfr verðr leiðr, ef lengi sitr annars fletjum á. Bú er betra, þótt lítit sé, halr er heima hverr; þótt tvær geitr eigi ok taugreftan sal, þat er þó betra en bæn. Bú er betra, þótt lítit sé, halr er heima hverr; blóðugt er hjarta, þeim er biðja skal sér í mál hvert matar. Vápnum sínum skal-a maðr velli á feti ganga framar, því at óvíst er at vita, nær verðr á vegum úti geirs of þörf guma. Fannk-a ek mildan mann eða svá matar góðan, at væri-t þiggja þegit, eða síns féar svági [glöggvan], at leið sé laun, ef þægi. Féar síns, er fengit hefr, skyli-t maðr þörf þola; oft sparir leiðum, þats hefr ljúfum hugat; margt gengr verr en varir. Vápnum ok váðum skulu vinir gleðjask; þat er á sjalfum sýnst; viðrgefendr ok endrgefendr erusk lengst vinir, ef þat bíðr at verða vel. Vin sínum skal maðr vinr vera ok gjalda gjöf við gjöf; hlátr við hlátri skyli hölðar taka en lausung við lygi. Vin sínum skal maðr vinr vera, þeim ok þess vin; en óvinar síns skyli engi maðr vinar vinr vera. Veiztu, ef þú vin átt, þann er þú vel trúir, ok vill þú af hánum gótt geta, geði skaltu við þann blanda ok gjöfum skipta, fara at finna oft. Ef þú átt annan, þanns þú illa trúir, vildu af hánum þó gótt geta, fagrt skaltu við þann mæla en flátt hyggja ok gjalda lausung við lygi. Það er enn of þann er þú illa trúir ok þér er grunr at hans geði, hlæja skaltu við þeim ok um hug mæla; glík skulu gjöld gjöfum. Ungr var ek forðum, fór ek einn saman, þá varð ek villr vega; auðigr þóttumk, er ek annan fann, maðr er manns gaman. Mildir, fræknir menn bazt lifa, sjaldan sút ala; en ósnjallr maðr uggir hotvetna, sýtir æ glöggr við gjöfum. Váðir mínar gaf ek velli at tveim trémönnum; rekkar þat þóttusk, er þeir rift höfðu; neiss er nökkviðr halr. Hrörnar þöll, sú er stendr þorpi á, hlýr-at henni börkr né barr; svá er maðr, sá er manngi ann. Hvat skal hann lengi lifa? Eldi heitari brennr með illum vinum friðr fimm daga, en þá sloknar, er inn sétti kemr, ok versnar allr vinskapr. Mikit eitt skal-a manni gefa; oft kaupir sér í litlu lof, með halfum hleif ok með höllu keri fekk ek mér félaga. Lítilla sanda lítilla sæva lítil eru geð guma; því allir menn urðu-t jafnspakir; half er öld hvar. Meðalsnotr skyli manna hverr; æva til snotr sé; þeim er fyrða fegrst at lifa, er vel margt vitu. Meðalsnotr skyli manna hverr, æva til snotr sé; því at snotrs manns hjarta verðr sjaldan glatt, ef sá er alsnotr, er á. Meðalsnotr skyli manna hverr, æva til snotr sé; örlög sín viti engi fyrir, þeim er sorgalausastr sefi. Brandr af brandi brenn, unz brunninn er, funi kveikisk af funa; maðr af manni verðr at máli kuðr, en til dælskr af dul. Ár skal rísa, sá er annars vill fé eða fjör hafa; sjaldan liggjandi ulfr lær of getr né sofandi maðr sigr. Ár skal rísa, sá er á yrkjendr fáa, ok ganga síns verka á vit; margt of dvelr, þann er um morgin sefr, hálfr er auðr und hvötum. Þurra skíða ok þakinna næfra, þess kann maðr mjöt, þess viðar, er vinnask megi mál ok misseri. Þveginn ok mettr ríði maðr þingi at, þótt hann sé-t væddr til vel; skúa ok bróka skammisk engi maðr né hests in heldr, þótt hann hafi-t góðan Snapir ok gnapir, er til sævar kemr, örn á aldinn mar; svá er maðr, er með mörgum kemr ok á formælendr fáa. Fregna ok segja skal fróðra hverr, sá er vill heitinn horskr; einn vita né annarr skal, þjóð veit, ef þrír ro. Ríki sitt skyli ráðsnotra hverr í hófi hafa; þá hann þat finnr, er með fræknum kemr at engi er einna hvatastr. -- -- -- -- orða þeira, er maðr öðrum segir oft hann gjöld of getr. Mikilsti snemma kom ek í marga staði, en til síð í suma; öl var drukkit, sumt var ólagat, sjaldan hittir leiðr í líð. Hér ok hvar myndi mér heim of boðit, ef þyrftak at málungi mat, eða tvau lær hengi at ins tryggva vinar, þars ek hafða eitt etit. Eldr er beztr með ýta sonum ok sólar sýn, heilyndi sitt, ef maðr hafa náir, án við löst at lifa. Er-at maðr alls vesall, þótt hann sé illa heill; sumr er af sonum sæll, sumr af frændum, sumr af fé ærnu, sumr af verkum vel. Betra er lifðum en sé ólifðum, ey getr kvikr kú; eld sá ek upp brenna auðgum manni fyrir, en úti var dauðr fyr durum. Haltr ríðr hrossi, hjörð rekr handar vanr, daufr vegr ok dugir, blindr er betri en brenndr séi, nýtr manngi nás. Sonr er betri, þótt sé síð of alinn eftir genginn guma; sjaldan bautarsteinar standa brautu nær, nema reisi niðr at nið. Tveir ro eins herjar, tunga er höfuðs bani; er mér í heðin hvern handar væni. Nótt verðr feginn sá er nesti trúir, skammar ro skips ráar; hverf er haustgríma; fjölð of viðrir á fimm dögum en meira á mánuði. Veit-a hinn, er vettki veit, margr verðr af aurum api; maðr er auðigr, annar óauðigr, skyli-t þann vítka váar. Deyr fé, deyja frændr, deyr sjalfr it sama, en orðstírr deyr aldregi, hveim er sér góðan getr. Deyr fé, deyja frændr, deyr sjalfr it sama, ek veit einn, at aldrei deyr: dómr um dauðan hvern. Fullar grindr sá ek fyr Fitjungs sonum, nú bera þeir vánar völ; svá er auðr sem augabragð, hann er valtastr vina. Ósnotr maðr, ef eignask getr fé eða fljóðs munuð, metnaðr hánum þróask, en mannvit aldregi, fram gengr hann drjúgt í dul. Þat er þá reynt, er þú að rúnum spyrr inum reginkunnum, þeim er gerðu ginnregin ok fáði fimbulþulr, þá hefir hann bazt, ef hann þegir. At kveldi skal dag leyfa, konu, er brennd er, mæki, er reyndr er, mey, er gefin er, ís, er yfir kemr, öl, er drukkit er. Í vindi skal við höggva, veðri á sjó róa, myrkri við man spjalla, mörg eru dags augu; á skip skal skriðar orka, en á skjöld til hlífar, mæki höggs, en mey til kossa. Við eld skal öl drekka, en á ísi skríða, magran mar kaupa, en mæki saurgan, heima hest feita, en hund á búi.";

int main(void)
{   
    const int num_blocks = sizeof(havamal) / AES_BLOCKLEN;
    
    LOG_INF("Embedded encryptor initialising...");

    k_sleep(K_MSEC(1000));
    
    struct AES_ctx ctx;
    
    AES_init_ctx_iv(&ctx, flag, iv);
    
    AES_CBC_encrypt_buffer(&ctx, havamal, num_blocks * AES_BLOCKLEN);
    
    k_sleep(K_MSEC(1000));

    LOG_INF("Printing ciphertext:");

    for (int i = 0; i < num_blocks; i++)
    {
        char blockstr[16];
        snprintf(blockstr, sizeof(blockstr), "block %d", i);
        
        LOG_HEXDUMP_INF(havamal + AES_BLOCKLEN * i, AES_BLOCKLEN, blockstr);
    }
}
